/**
 * Unit tests for SubLine.intersection
 */
public class SubLine_intersection_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_InsideBoth_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (2,2)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        // Line 2: (0,2) to (2,0)
        SubLine sub2 = new SubLine(new Vector2D(0, 2), new Vector2D(2, 0));

        // Intersection is at (1,1)
        Vector2D result = sub1.intersection(sub2, true);

        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(1.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_InsideBoth_IncludeEndPointsFalse() {
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(2, 2));
        SubLine sub2 = new SubLine(new Vector2D(0, 2), new Vector2D(2, 0));

        Vector2D result = sub1.intersection(sub2, false);

        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(1.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_AtEndPoint_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (1,1)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(1, 1));
        // Line 2: (1,1) to (2,0)
        SubLine sub2 = new SubLine(new Vector2D(1, 1), new Vector2D(2, 0));

        // Intersection is (1,1), which is an endpoint
        Vector2D result = sub1.intersection(sub2, true);

        assertEquals(1.0, result.getX(), EPSILON);
        assertEquals(1.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_AtEndPoint_IncludeEndPointsFalse() {
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(1, 1));
        SubLine sub2 = new SubLine(new Vector2D(1, 1), new Vector2D(2, 0));

        // (1,1) is an endpoint, so loc will be BOUNDARY, not INSIDE.
        // For includeEndPoints=false, it requires loc == INSIDE.
        Vector2D result = sub1.intersection(sub2, false);

        assertNull(result);
    }

    @Test
    public void testIntersection_OutsideOne_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (1,1)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(1, 1));
        // Line 2: (2,0) to (3,3) -> Intersects line 1 extension at (1.5, 1.5)
        SubLine sub2 = new SubLine(new Vector2D(2, 0), new Vector2D(3, 3));

        Vector2D result = sub1.intersection(sub2, true);

        assertNull(result);
    }

    @Test
    public void testIntersection_OutsideOne_IncludeEndPointsFalse() {
        // Line 1: (0,0) to (1,1)
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(1, 1));
        // Line 2: (2,0) to (3,3)
        SubLine sub2 = new SubLine(new Vector2D(2, 0), new Vector2D(3, 3));

        Vector2D result = sub1.intersection(sub2, false);

        assertNull(result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIntersection_ParallelLines() {
        // Parallel lines do not have an intersection point in the underlying Line logic
        // Usually throws IllegalArgumentException or returns null depending on implementation
        SubLine sub1 = new SubLine(new Vector2D(0, 0), new Vector2D(1, 0));
        SubLine sub2 = new SubLine(new Vector2D(0, 1), new Vector2D(1, 1));

        sub1.intersection(sub2, true);
    }
}
